/* ===== module: workout/fork-pause-queue.js ===== */
/* FORK — SESSION QUEUE + DELOAD WEEKS + PROGRAM WEEK CORE
   (Research Round 2 #3 + #4). Pure functions only — no DOM, no
   storage, no globals read at call time — so the unit suite can
   load this file on its own (tests/fork-pause-queue.test.js) and
   the coordinator can wire the UI against a stable API.

   V2 BETA PORT (S7): ONE semantic override over the fork's
   shipped form — the pass derivation is MODEL B (user ruling
   2026-10-22, D2), not the fork's Model A: the derived next
   follows the MOST RECENTLY COMPLETED session in the rotation
   (see replayPassEvents). Transplanted from the Model B build
   in beta-port-s6 (builder-report-s6.md §3). Everything else —
   the stored ledger ops, deload weeks, the calendar week, the
   registry metadata below — is the fork's final form unchanged.

   What this answers, in plain language:
   - Session queue: a program follows COMPLETION ORDER, not the
     calendar. "Next up" is a place in the workout rotation, not a
     weekday. For the next-up session the user can Skip it (the
     skip is RECORDED in a ledger — it feeds adherence counts
     later, it is never a silent hole), Do it today (next-up stays
     next-up, marked as planned for today), or Push the week (the
     whole rotation shifts a week later; order untouched). The
     program cover today counts a calendar week as done or not
     done — the queue is the honest record underneath that.
   - Deload weeks: a one-tap, user-marked week (below) whose
     sessions get reduced planned loads from the engine.
   - The program week: forkEffectiveProgramWeek is the plain
     calendar week from the program's start date — the day-count
     math programWeekAtDate (pages/programs.js) layers the
     completed-pass count over (FR-117).

   FORK v1.992 (FR-191): program PAUSE is REMOVED entirely
   (user direction 2026-10-21 — the button and the code around it
   are "not needed"). The pause state readers/transitions, the
   week freeze (paused days are no longer subtracted — paused
   time now counts as elapsed calendar time), the return ramp
   and its first-week-back holds experiment, the paused cover
   card and every paused-state surface are deleted with it. A
   stored program.forkPause record is inert data from here on:
   never read, never written, no migration. This module keeps
   its filename — the queue, deload and week functions it still
   carries are what the name's second half always referred to.

   State shapes (additive fields ON the program object, so they
   persist and sync with the program blob — persistence.js stores
   `activeProgram` whole; a program without these fields simply
   carries a fresh queue, no migration):
     program.forkQueue = {
       order: [workoutUid, ...],   // rotation snapshot
       cursor: 0,                  // index of next-up in `order`
       entries: [{ uid, action, date }],  // append-only ledger;
         // action: 'completed' | 'skipped' | 'do-today' | 'push-week'
         // | 'unskipped' (FORK v1.991.7 — the compensating entry
         // forkQueueUnskip appends; push-week entries carry uid: null)
       pushedWeeks: 0,
       pending: null | { uid, date },     // set by Do today
     }

   FORK v1.991.7 (Batch D — DQ-1/DQ-2 cover wiring): the prescribed
   next is DERIVED from the ledger, never read from the stored
   cursor. forkQueuePassState() replays the entries pass by pass: a
   session is resolved this pass when its latest pass act is a
   completion, or a skip not later un-skipped; when every session
   in the rotation is resolved the pass wraps and all sessions are
   live again. `cursor` is still maintained by the mutating ops as
   a convenience snapshot (forkNextUpUid reads it), but the cover
   and forkQueueSkip's own validation follow the derivation, so an
   un-skip — which has no stored-cursor move — still lands exactly:
   un-skipping a session makes it next again whenever everything
   before it in the rotation is resolved.

   FORK v1.991.17 (FR-75): the derivation optionally merges
   completions read off the workout logs themselves
   (forkQueuePassEvents). The cover's This week rows read the
   logs; the pointer read only the ledger — a finish that never
   reached the ledger (logged before the queue existed, finished
   with the queue off, re-saved by an edit) showed Done on the
   row while the pointer still named that session next. One
   merged derivation now feeds both.

   Reality check against the tree (2026-10-19): the active program
   is { id, name, length (weeks), workouts: [{ uid, name,
   template }], startedAt, progression } (pages/programs.js);
   programWeekAtDate() derives the week from calendar days since
   startedAt, and suggestedProgramWorkout() picks the least
   recently logged ready workout. This module does not replace
   either — forkEffectiveProgramWeek() is the same day-count math
   in pure form, and the queue makes the completion order
   explicit and recordable.

   All functions are pure and non-mutating: transitions and queue
   operations return NEW objects and leave their inputs untouched.
   All date math uses UTC day ordinals on 'YYYY-MM-DD' strings —
   the same local-calendar-day approach as programWeekAtDate — so
   weeks never drift across a DST change.

   The session queue is PERMANENT (it graduated with the Fork
   experiments framework's removal, user ruling 2026-10-23); the
   pure core never checked a toggle and still does not.

   Depends on: nothing. */
(function () {
  'use strict';

  /* ---------- small shared helpers ---------- */

  const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

  /* True only for a real calendar date in YYYY-MM-DD form. */
  function isIsoDate(value) {
    if (typeof value !== 'string' || !ISO_DATE_RE.test(value)) return false;
    const [y, m, d] = value.split('-').map(Number);
    if (m < 1 || m > 12 || d < 1 || d > 31) return false;
    const dt = new Date(Date.UTC(y, m - 1, d));
    return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
  }

  /* UTC day ordinal for an ISO date (null when invalid) — the same
     day-count basis programWeekAtDate uses in pages/programs.js. */
  function dayNum(iso) {
    if (!isIsoDate(iso)) return null;
    const [y, m, d] = iso.split('-').map(Number);
    return Math.floor(Date.UTC(y, m - 1, d) / 86400000);
  }

  /* Whole days from `fromIso` to `toIso` (negative when reversed),
     or null when either date is invalid. */
  function forkDaysBetween(fromIso, toIso) {
    const a = dayNum(fromIso), b = dayNum(toIso);
    if (a === null || b === null) return null;
    return b - a;
  }

  function clampInt(n, lo, hi) {
    return Math.min(hi, Math.max(lo, n));
  }

  /* Programs persist as JSON, so a JSON round-trip is a faithful
     deep clone; it also guarantees the caller's object is never
     mutated through a shared nested reference. */
  function clone(value) {
    return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
  }

  /* The anchor every program-week count runs from.
     PPL fix batch (2026-10-28, B4): weeks used to count from the
     CREATION day (program.startedAt), so a program created on a
     Wednesday but first trained on a Monday ran Wed–Tue weeks
     forever — week 1 showed 2 of 6, adherence read a week short,
     and a "this week" deload mark covered a span that was not the
     training week. The anchor is now the FIRST COMPLETED SESSION's
     date for this program (the logs carry programId + dates; a
     Restart's forkRunStart floors the scan to the current run,
     mirroring forkProgramLogCompletions). Creation-time startedAt
     remains the fallback before any session exists, and stays the
     record's display age — only week math moves. Derived at read
     time from the live log stream, so programs already mid-run
     re-anchor without a migration. */
  function forkProgramWeekAnchorIso(program) {
    if (!program || typeof program !== 'object') return null;
    const runFloor = typeof program.forkRunStart === 'string' ? program.forkRunStart : null;
    let first = null;
    try {
      const completed = (typeof workoutState !== 'undefined' && workoutState && Array.isArray(workoutState.completed))
        ? workoutState.completed : [];
      for (const log of completed) {
        if (!log || log.programId !== program.id) continue;
        const d = typeof log.isoDate === 'string' ? log.isoDate : (typeof log.date === 'string' ? log.date : null);
        if (!isIsoDate(d)) continue;
        if (runFloor && d < runFloor) continue;
        if (first === null || d < first) first = d;
      }
    } catch (_) { /* no readable log stream — fall through to startedAt */ }
    if (first !== null) return first;
    return isIsoDate(program.startedAt) ? program.startedAt : null;
  }

  /* The program week: the calendar week containing `dateIso`,
     counted in whole weeks from the program's week anchor (the
     first completed session's date — B4 above; the creation date
     only until a session exists) and clamped to [1, length] —
     programWeekAtDate's own day-count math in pure form. Returns
     null for a missing program.
     FORK v1.992 (FR-191): the pause offset is gone with the
     pause feature — no paused days are subtracted, so time spent
     paused counts as elapsed calendar time; a stored forkPause
     record is never read here. */
  function forkEffectiveProgramWeek(program, dateIso) {
    if (!program || typeof program !== 'object') return null;
    const point = dayNum(dateIso);
    const start = dayNum(forkProgramWeekAnchorIso(program));
    if (point === null || start === null) return 1;
    const length = Number(program.length) > 0 ? Math.floor(Number(program.length)) : 1;
    const elapsedCalendar = Math.max(0, point - start);
    return clampInt(1 + Math.floor(elapsedCalendar / 7), 1, length);
  }

  /* ---------- deload weeks (FORK v1.991.19, Batch N1) ----------

     A one-tap, user-marked deload week, stored on the program
     record (so it persists and syncs with the program blob):
       program.forkDeload = { weeks: [4, ...] }   // effective
         // program-week indices (the week numbering
         // forkEffectiveProgramWeek returns)
     This is NOT the %1RM wave panel's weeklyDeloads (that is a
     progression-config schedule read by isDeloadWeek in
     formulas/program-math.js); the fork deload is a whole-program
     week the user marks from the cover, and the engine gate in
     workout/progression.js reads it through forkIsDeloadWeek.
     The recorded week is the EFFECTIVE week, so a deload marked
     for this week stays attached to this program week. */

  /* Normalized deload state: sorted unique whole week indices
     ≥ 1; junk (non-numbers, duplicates, week 0) is dropped. */
  function forkDeloadState(program) {
    if (!program || typeof program !== 'object') return { weeks: [] };
    const raw = program.forkDeload;
    const list = raw && Array.isArray(raw.weeks) ? raw.weeks : [];
    const weeks = [...new Set(list
      .map(w => Math.floor(Number(w)))
      .filter(w => Number.isFinite(w) && w >= 1))].sort((a, b) => a - b);
    return { weeks };
  }

  /* True when `week` (an effective program week) is a marked
     deload week on this program. */
  function forkIsDeloadWeek(program, week) {
    const w = Math.floor(Number(week));
    if (!Number.isFinite(w) || w < 1) return false;
    return forkDeloadState(program).weeks.includes(w);
  }

  /* Transition: mark `week` as a deload week. Returns a NEW
     program; marking an already-marked week changes nothing
     beyond normalization. Bad weeks change nothing. */
  function forkMarkDeloadWeek(program, week) {
    if (!program || typeof program !== 'object') return program;
    const next = clone(program);
    const state = forkDeloadState(next);
    const w = Math.floor(Number(week));
    if (Number.isFinite(w) && w >= 1 && !state.weeks.includes(w)) state.weeks.push(w);
    state.weeks.sort((a, b) => a - b);
    next.forkDeload = state;
    return next;
  }

  /* Transition: un-mark `week` (Cancel deload). Returns a NEW
     program; sessions already logged in that week keep the loads
     they were logged with — only the marker is removed. */
  function forkClearDeloadWeek(program, week) {
    if (!program || typeof program !== 'object') return program;
    const next = clone(program);
    const state = forkDeloadState(next);
    const w = Math.floor(Number(week));
    next.forkDeload = { weeks: state.weeks.filter(x => x !== w) };
    return next;
  }

  /* The deload load scale for a LIVE session draft — the engine
     gate's twin (progression.js forkDeloadSession): the draft must
     be a live session of the active program (never a history edit,
     never another program's or a saved workout's draft), and the
     week is the effective week at the DRAFT'S date, so a session
     started in a deload week stays a deload session after the
     calendar rolls over. The percent itself is the shared
     forkDeloadScaleForWeek determination (formulas/program-math.js
     — the formulas layer loads in every context, so the wave-flag
     half never depends on this file being present). Returns the
     percent, or null. */
  function forkDeloadSessionScale(draft) {
    if (!draft || draft.editingId || !draft.programId) return null;
    const program = (typeof workoutState !== 'undefined' && workoutState) ? workoutState.activeProgram : null;
    if (!program || program.id !== draft.programId) return null;
    const dateStr = (typeof draft.date === 'string' && draft.date) ? draft.date
      : (typeof localIsoDate === 'function' ? localIsoDate() : null);
    const week = forkEffectiveProgramWeek(program, dateStr);
    if (!(week > 0)) return null;
    return (typeof forkDeloadScaleForWeek === 'function') ? forkDeloadScaleForWeek(program, week) : null;
  }

  /* ---------- session queue ---------- */

  const QUEUE_ACTIONS = ['completed', 'skipped', 'do-today', 'push-week', 'unskipped'];

  function sanitizeQueue(raw, fallbackOrder) {
    const order = (Array.isArray(raw && raw.order) ? raw.order : fallbackOrder || [])
      .filter(uid => typeof uid === 'string' && uid);
    const entries = (Array.isArray(raw && raw.entries) ? raw.entries : [])
      .filter(e => e && QUEUE_ACTIONS.includes(e.action) && isIsoDate(e.date))
      .map(e => ({ uid: typeof e.uid === 'string' ? e.uid : null, action: e.action, date: e.date }));
    const cursorRaw = Math.floor(Number(raw && raw.cursor) || 0);
    const pendingRaw = raw && raw.pending;
    const pending = pendingRaw && typeof pendingRaw.uid === 'string' && order.includes(pendingRaw.uid) && isIsoDate(pendingRaw.date)
      ? { uid: pendingRaw.uid, date: pendingRaw.date } : null;
    return {
      order,
      cursor: order.length ? ((cursorRaw % order.length) + order.length) % order.length : 0,
      entries,
      pushedWeeks: Math.max(0, Math.floor(Number(raw && raw.pushedWeeks) || 0)),
      pending,
    };
  }

  /* A fresh queue over a program's workout rotation. */
  function forkQueueInit(program) {
    const order = (Array.isArray(program && program.workouts) ? program.workouts : [])
      .map(w => w && w.uid).filter(uid => typeof uid === 'string' && uid);
    return sanitizeQueue(null, order);
  }

  /* Normalized queue state from a program (its stored forkQueue,
     or a fresh one over its rotation) or from a queue object
     itself. Always returns a fresh object. */
  function forkQueueState(programOrQueue) {
    if (!programOrQueue || typeof programOrQueue !== 'object') return sanitizeQueue(null, []);
    if (Array.isArray(programOrQueue.workouts)) {
      return sanitizeQueue(programOrQueue.forkQueue, forkQueueInit(programOrQueue).order);
    }
    return sanitizeQueue(programOrQueue, []);
  }

  /* A NEW program carrying `queue` as its forkQueue — the one
     assignment the coordinator makes after any queue operation,
     followed by its usual persist + render. */
  function forkWithQueue(program, queue) {
    if (!program || typeof program !== 'object') return program;
    const next = clone(program);
    next.forkQueue = forkQueueState(queue);
    return next;
  }

  function forkNextUpUid(queue) {
    const q = forkQueueState(queue);
    return q.order.length ? q.order[q.cursor] : null;
  }

  function forkQueuePending(queue) {
    const q = forkQueueState(queue);
    return q.pending ? { ...q.pending } : null;
  }

  /* How far Push week has shifted the schedule, in days. */
  function forkQueueScheduleOffsetDays(queue) {
    return forkQueueState(queue).pushedWeeks * 7;
  }

  /* Skip the next-up session. The skip is RECORDED in the ledger
     (it feeds the adherence counts) and next-up moves to the
     following session in the rotation, wrapping at the end.
     Skipping anything other than the next-up session, or with a
     bad date, changes nothing — a skip is an explicit act on the
     session that is up, never a silent edit.
     FORK v1.991.7: "next-up" here is the DERIVED next
     (forkQueuePassState), not the stored cursor — after an
     un-skip the two can disagree, and the derivation is the one
     the cover shows, so it is the one a skip must act on.
     FORK v1.991.17 (FR-75): the validation derivation takes the
     caller's log completions too (same merged stream the cover
     derives its card from), so a skip is validated against the
     next the user actually sees. Only the skip is appended —
     the stored entries stay exactly the ledger's own. */
  function forkQueueSkip(queue, uid, dateIso, logCompletions) {
    const q = forkQueueState(queue);
    if (!q.order.length || !isIsoDate(dateIso) || uid !== forkQueuePassState(q, logCompletions).nextUid) return q;
    q.entries = [...q.entries, { uid, action: 'skipped', date: dateIso }];
    if (q.pending && q.pending.uid === uid) q.pending = null;
    q.cursor = (q.cursor + 1) % q.order.length;
    return q;
  }

  /* Do the next-up session today: next-up stays next-up and is
     marked as planned for `dateIso`; the choice is recorded.
     Nothing is counted as done or skipped — the session still
     has to happen. */
  function forkQueueDoToday(queue, uid, dateIso) {
    const q = forkQueueState(queue);
    if (!q.order.length || !isIsoDate(dateIso) || uid !== q.order[q.cursor]) return q;
    q.entries = [...q.entries, { uid, action: 'do-today', date: dateIso }];
    q.pending = { uid, date: dateIso };
    return q;
  }

  /* Push the week: the whole rotation shifts a week later. Order
     and next-up are untouched; the shift is counted (and readable
     as days via forkQueueScheduleOffsetDays) and recorded. */
  function forkQueuePushWeek(queue, dateIso) {
    const q = forkQueueState(queue);
    if (!q.order.length || !isIsoDate(dateIso)) return q;
    q.pushedWeeks += 1;
    q.entries = [...q.entries, { uid: null, action: 'push-week', date: dateIso }];
    return q;
  }

  /* Record a completion. Completing the next-up session advances
     next-up to the following session; completing any other
     session in the rotation is recorded without reordering —
     the queue follows the order sessions are completed in, it
     does not reshuffle around them. */
  function forkQueueComplete(queue, uid, dateIso) {
    const q = forkQueueState(queue);
    if (!q.order.length || !isIsoDate(dateIso) || !q.order.includes(uid)) return q;
    q.entries = [...q.entries, { uid, action: 'completed', date: dateIso }];
    if (q.pending && q.pending.uid === uid) q.pending = null;
    if (uid === q.order[q.cursor]) q.cursor = (q.cursor + 1) % q.order.length;
    return q;
  }

  /* FORK v1.991.17 (FR-75): the event stream a pass derivation
     replays. The ledger is the recorded acts; `logCompletions` is
     the optional second source — completions read off the actual
     workout logs ([{ uid, date }]) — merged in so a finish that
     never reached the ledger (a log from before the queue
     existed, a finish while the queue was off, an edit-finish)
     still resolves its session. A log completion the ledger
     already recorded (same uid, same date) is dropped, so the
     finish is never replayed twice. The merged stream replays in
     date order (stable: ledger entries precede log completions
     sharing their date). The synthesized events are NEVER
     written back into the stored ledger — they re-derive from
     the logs on every read. */
  function forkQueuePassEvents(q, logCompletions) {
    const recorded = new Set(q.entries
      .filter(e => e.action === 'completed' && e.uid)
      .map(e => e.uid + '|' + e.date));
    const fromLogs = (Array.isArray(logCompletions) ? logCompletions : [])
      .filter(c => c && typeof c.uid === 'string' && q.order.includes(c.uid)
        && isIsoDate(c.date) && !recorded.has(c.uid + '|' + c.date))
      .map(c => ({ uid: c.uid, action: 'completed', date: c.date }));
    if (!fromLogs.length) return q.entries;
    return [...q.entries, ...fromLogs].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  }

  /* FORK v1.991.7 — the derived pass state (DQ-1/DQ-2). Replays the
     ledger in order, tracking which sessions are resolved in the
     CURRENT pass: a completion resolves; a skip resolves unless a
     later 'unskipped' entry in the same pass cancels it (a skip
     never overrides a completion — finishing is terminal for the
     pass); when every session in the rotation is resolved the
     pass ends and a fresh pass begins with all sessions live.
     'do-today' and 'push-week' resolve nothing. Returns
     { resolved: { uid: 'completed' | 'skipped' }, nextUid,
     cursor } — nextUid is the earliest unresolved session in
     rotation order (null only for an empty rotation), and cursor
     is its index. Pure derivation: nothing is stored, so the
     answer can never drift from the ledger.
     FORK v1.991.17 (FR-75): the replay runs over
     forkQueuePassEvents — the ledger merged with the caller's
     log completions — so the pointer and any log-based readout
     (the cover's This week rows) share ONE derivation of
     "completed in current pass" and cannot disagree. */
  /* FORK v1.991.35 (FR-117): the ONE pass replay, shared by the
     pass state and the completed-pass count so the two can never
     drift. Replays the merged event stream (forkQueuePassEvents);
     when `asOfIso` is a valid date, events dated after it do not
     count — the pass state AS OF that date (the week helper asks
     about past dates too, and a pass completed later must not
     rewrite which week an earlier date sat in). A pass completes
     the moment every session in the rotation is resolved (done or
     skipped — a skip completes a pass the same way a done does);
     the resolved set then clears and the next pass begins. */
  /* V2 BETA PORT (S7) — MODEL B (user ruling 2026-10-22, D2;
     overrides the fork's shipped Model A replay described in
     the FR-117 note above): the derived next follows the MOST
     RECENTLY COMPLETED session. The replay tracks, per pass,
     each session's resolution — 'completed', 'skipped', or
     'passed' — and the rotation index of the most recent
     completion (the anchor). A completion at index i:
       · resolves its session 'completed' (finishing is
         terminal for the pass — it beats a skip and a pass);
       · when i is AHEAD of the anchor, every still-unresolved
         session between the anchor and i is PASSED: resolved
         for this pass, but not a completion — it feeds no
         adherence count, earns no Done state, and the session
         stays startable from the list;
       · moves the anchor to i. A completion at or behind the
         anchor (a passed or un-skipped session done from the
         list, a repeat) resolves its session and moves
         nothing — the pointer is already past it.
     A skip resolves its session and never moves the anchor;
     an un-skip clears a skip (an un-skipped session behind
     the anchor is live again for the pass, but the pointer
     still follows the anchor until nothing ahead is open).
     When every session is resolved the pass completes and a
     fresh pass begins. 'passed' is an internal resolution:
     forkQueuePassState strips it from the returned map, so
     consumers see exactly the fork's { completed | skipped }
     shape — a passed session reads as neither done nor
     skipped, it is simply not next. */
  function replayPassEvents(q, logCompletions, asOfIso) {
    const resolved = {};
    let passes = 0;
    let anchor = -1;
    const asOf = isIsoDate(asOfIso) ? asOfIso : null;
    for (const e of forkQueuePassEvents(q, logCompletions)) {
      if (asOf && e.date > asOf) continue;
      if (!e.uid || !q.order.includes(e.uid)) continue;
      const i = q.order.indexOf(e.uid);
      if (e.action === 'completed') {
        if (i > anchor) {
          for (let j = anchor + 1; j < i; j++) {
            if (!resolved[q.order[j]]) resolved[q.order[j]] = 'passed';
          }
          anchor = i;
        }
        resolved[e.uid] = 'completed';
      }
      else if (e.action === 'skipped') { if (resolved[e.uid] !== 'completed') resolved[e.uid] = 'skipped'; }
      else if (e.action === 'unskipped') { if (resolved[e.uid] === 'skipped') delete resolved[e.uid]; }
      if (q.order.length && q.order.every(u => resolved[u])) {
        passes++;
        for (const u of q.order) delete resolved[u];
        anchor = -1;
      }
    }
    return { resolved, passes, anchor };
  }

  function forkQueuePassState(queue, logCompletions) {
    const q = forkQueueState(queue);
    const { resolved, anchor } = replayPassEvents(q, logCompletions, null);
    /* Model B next: the earliest unresolved session AHEAD of
       the anchor; when nothing ahead is open, the earliest
       unresolved session overall (an un-skipped session behind
       the anchor is the pass's last open business). 'passed'
       sessions are resolved for this — they are never next. */
    const open = q.order.filter(u => !resolved[u]);
    const nextUid = open.find(u => q.order.indexOf(u) > anchor) || open[0] || null;
    const publicResolved = {};
    for (const u of q.order) {
      if (resolved[u] === 'completed' || resolved[u] === 'skipped') publicResolved[u] = resolved[u];
    }
    return { resolved: publicResolved, nextUid, cursor: nextUid ? q.order.indexOf(nextUid) : 0 };
  }

  /* FORK v1.991.35 (FR-117): how many passes through the rotation
     the merged stream has COMPLETED (optionally as of a date) —
     the count the program week follows: the current pass is
     number (completed passes + 1), so finishing or skipping the
     last open session of a pass turns the week the moment it
     happens instead of when the calendar gets there. A skip is
     a resolution here, never a completion: this count feeds the
     week only — adherence and Stats read completions off the
     logs and the ledger's own action counts, never this. */
  function forkQueueCompletedPasses(queue, logCompletions, asOfIso) {
    const q = forkQueueState(queue);
    if (!q.order.length) return 0;
    return replayPassEvents(q, logCompletions, asOfIso || null).passes;
  }

  /* The derived cursor: index of the prescribed next session in
     the rotation, from the ledger alone (DQ-1). */
  function forkQueueDeriveCursor(queue, logCompletions) {
    return forkQueuePassState(queue, logCompletions).cursor;
  }

  /* The prescribed next session's uid, derived from the ledger
     (Model B, D2: the session following the most recently
     completed one among those not done or skipped this pass —
     see replayPassEvents). */
  function forkQueueDerivedNextUid(queue, logCompletions) {
    return forkQueuePassState(queue, logCompletions).nextUid;
  }

  /* FORK v1.991.7 — Un-skip (DQ-2): an append-only compensating
     entry that returns a skipped session to this pass. It acts
     only on a session the derived pass state currently reads as
     skipped — un-skipping anything else (a completed session, a
     session never skipped, a bad date) records nothing. The
     ledger is never rewritten: the original skip stays on the
     record, and derivation reads the pair. Because the session
     could only have been skipped while it was next-up, everything
     before it in the rotation is already resolved, so it becomes
     next-up again automatically. */
  function forkQueueUnskip(queue, uid, dateIso, logCompletions) {
    const q = forkQueueState(queue);
    if (!q.order.length || !isIsoDate(dateIso) || !q.order.includes(uid)) return q;
    /* FORK v1.991.17 (FR-75): resolved is read off the same
       merged derivation the cover renders (ledger + log
       completions), for the same reason as forkQueueSkip. */
    if (forkQueuePassState(q, logCompletions).resolved[uid] !== 'skipped') return q;
    q.entries = [...q.entries, { uid, action: 'unskipped', date: dateIso }];
    return q;
  }

  /* Adherence counts over the recorded ledger — the numbers the
     Stats adherence line (Research Round 2 §G) will read. Only
     recorded acts count: `resolved` is sessions with an outcome
     (completed or skipped); a session nobody acted on is not in
     these numbers at all. */
  function forkQueueAdherence(queue) {
    const q = forkQueueState(queue);
    const count = action => q.entries.filter(e => e.action === action).length;
    const completed = count('completed');
    const skipped = count('skipped');
    return {
      completed,
      skipped,
      doToday: count('do-today'),
      weekPushes: q.pushedWeeks,
      resolved: completed + skipped,
      recorded: q.entries.length,
    };
  }

  const api = {
    forkDaysBetween,
    forkDeloadState,
    forkIsDeloadWeek,
    forkMarkDeloadWeek,
    forkClearDeloadWeek,
    forkDeloadSessionScale,
    forkEffectiveProgramWeek,
    forkProgramWeekAnchorIso,
    forkQueueInit,
    forkQueueState,
    forkWithQueue,
    forkNextUpUid,
    forkQueuePending,
    forkQueueScheduleOffsetDays,
    forkQueueSkip,
    forkQueueDoToday,
    forkQueuePushWeek,
    forkQueueComplete,
    forkQueuePassState,
    forkQueueCompletedPasses,
    forkQueueDeriveCursor,
    forkQueueDerivedNextUid,
    forkQueueUnskip,
    forkQueueAdherence,
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  const root = typeof globalThis !== 'undefined' ? globalThis : null;
  if (root) for (const [name, value] of Object.entries(api)) root[name] = value;
  if (typeof window !== 'undefined') for (const [name, value] of Object.entries(api)) window[name] = value;
})();
